class Solution {
public:
    int mySqrt(int x) {
        if (x < 2) return x;
        long long low = 1, high = x / 2, ans = 1;
        while (low <= high) {
            long long mid = low + (high - low) / 2;
            if (mid * mid <= x) {
                ans = mid;
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        return (int)ans;
    }
};

