var mySqrt = function(x) {
    if (x < 2) return x;
    let low = 1, high = Math.floor(x / 2), ans = 1;
    while (low <= high) {
        const mid = Math.floor((low + high) / 2);
        if (mid * mid <= x) {
            ans = mid;
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }
    return ans;
};
